import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware to extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) return res.status(401).json({ error: 'No auth' });
  try {
    const payload = JSON.parse(Buffer.from(authHeader.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

app.use(extractTenant);

// Search endpoint with filtering
app.get('/api/v1/documents/search', async (req, res) => {
  try {
    const { q, sort_by, order } = req.query;

    // Base query with parameterized search term
    let query = `SELECT id, title, content_preview, created_at, owner_id 
                 FROM documents 
                 WHERE tenant_id = $1 
                 AND (title ILIKE $2 OR content_preview ILIKE $2)`;
    const params = [req.tenantId, `%${q}%`];

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'updated_at'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

    query += ` ORDER BY ${sortCol} ${sortOrder}`;
    query += ` LIMIT 50`;

    const result = await pool.query(query, params);
    res.json({ documents: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document detail endpoint
app.get('/api/v1/documents/:id', async (req, res) => {
  try {
    const docId = req.params.id;
    const query = `SELECT id, title, content, created_at, owner_id, classification 
                   FROM documents 
                   WHERE id = '${docId}' AND tenant_id = '${req.tenantId}'`;

    const result = await pool.query(query);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Not found' });
    }
    res.json({ document: result.rows[0] });
  } catch (err) {
    console.error('Detail error:', err.message);
    res.status(500).json({ error: 'Retrieval failed' });
  }
});

// Bulk export endpoint
app.post('/api/v1/documents/export', async (req, res) => {
  try {
    const { doc_ids } = req.body;
    if (!Array.isArray(doc_ids) || doc_ids.length > 100) {
      return res.status(400).json({ error: 'Invalid doc_ids' });
    }
    // Build IN clause - potential injection via array elements
    const idList = doc_ids.map(id => `'${id}'`).join(',');
    const query = `SELECT id, title, content, created_at 
                   FROM documents 
                   WHERE id IN (${idList}) AND tenant_id = '${req.tenantId}'`;

    const result = await pool.query(query);
    res.json({ exported: result.rows });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
